    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        tenTruong   = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        // Khởi tạo tuần có thứ 2 hiện tại (hoặc tuần hiện tại)
        _weekStart = GetMondayOfWeek(DateTime.Today);

        await LoadThucDon();
    }

    // ── LOAD DATA ──
    private async Task LoadThucDon()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            var list = await ThongBaoServices.hGetThucDonByTuan(_maTruongBo, _weekStart, _weekEnd);
            _menuDict = list
                .GroupBy(t => (t.ngay.Date, t.id_bua))
                .ToDictionary(g => g.Key, g => g.ToList());
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadThucDon error: {ex.Message}");
            await ShowToast("Lỗi tải thực đơn!", "error");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── WEEK NAVIGATION ──
    private async Task PrevWeek()
    {
        _weekStart = _weekStart.AddDays(-7);
        await LoadThucDon();
    }

    private async Task NextWeek()
    {
        _weekStart = _weekStart.AddDays(7);
        await LoadThucDon();
    }

    private async Task GoToCurrentWeek()
    {
        _weekStart = GetMondayOfWeek(DateTime.Today);
        await LoadThucDon();
    }

    private static DateTime GetMondayOfWeek(DateTime date)
    {
        int diff = (7 + (date.DayOfWeek - DayOfWeek.Monday)) % 7;
        return date.AddDays(-diff).Date;
    }

    private static int GetIsoWeekNumber(DateTime date)
    {
        return System.Globalization.ISOWeek.GetWeekOfYear(date);
    }

    // ── ADD MODAL ──
    private void OpenAddModal()
    {
        _addNgay       = _weekStart.ToString("yyyy-MM-dd");
        _addIdBua      = 1;
        _addTenThucDon = "";
        _addError      = "";
        _showAddModal  = true;
    }

    private void OpenAddModalFor(DateTime date, int idBua)
    {
        _addNgay       = date.ToString("yyyy-MM-dd");
        _addIdBua      = idBua;
        _addTenThucDon = "";
        _addError      = "";
        _showAddModal  = true;
    }

    private void CloseAddModal()
    {
        _showAddModal = false;
    }

    private async Task ExecuteAdd()
    {
        _addError = "";
        if (string.IsNullOrWhiteSpace(_addTenThucDon))
        {
            _addError = "Vui lòng nhập tên món ăn.";
            return;
        }

        if (!DateTime.TryParse(_addNgay, out var ngayParsed))
        {
            _addError = "Ngày không hợp lệ.";
            return;
        }

        _isProcessing = true;
        StateHasChanged();
        try
        {
            var tenBua = _buaList.FirstOrDefault(b => b.IdBua == _addIdBua)?.TenBua ?? "";
            bool ok = await ThongBaoServices.haddThucDon(
                _maTruongBo, _addIdBua, tenBua, ngayParsed, _addTenThucDon.Trim());

            if (ok)
            {
                _showAddModal = false;
                await LoadThucDon();
                await ShowToast("Đã thêm món ăn thành công!", "success");
            }
            else
            {
                _addError = "Món ăn này đã tồn tại trong thực đơn.";
            }
        }
        catch (Exception ex)
        {
            _addError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isProcessing = false;
            StateHasChanged();
        }
    }

