    private async Task OnFileSelected(InputFileChangeEventArgs e)
    {
        _importError = "";
        var file = e.File;
        if (file == null) return;

        if (!file.Name.EndsWith(".xlsx", StringComparison.OrdinalIgnoreCase) &&
            !file.Name.EndsWith(".xls",  StringComparison.OrdinalIgnoreCase))
        {
            _importError = "Chỉ chấp nhận file .xlsx hoặc .xls";
            StateHasChanged();
            return;
        }

        try
        {
            using var ms = new System.IO.MemoryStream();
            await file.OpenReadStream(maxAllowedSize: 5 * 1024 * 1024).CopyToAsync(ms);
            ms.Position = 0;

            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            using var ep    = new ExcelPackage(ms);
            var sheet = ep.Workbook.Worksheets[0];

            if (sheet == null || sheet.Dimension == null || sheet.Dimension.Rows < 5)
            {
                _importError = "File không hợp lệ hoặc không có dữ liệu!";
                StateHasChanged();
                return;
            }

            // Đọc ngày bắt đầu / kết thúc
            // Thử đọc giá trị gốc từ ô (có thể là số OADate nếu Excel lưu dạng Date)
            var startCell = sheet.Cells[2, 2];
            var endCell   = sheet.Cells[3, 2];

            if (!TryParseFlexibleDate(startCell, out var ngayBatDau) ||
                !TryParseFlexibleDate(endCell,   out var ngayKetThuc))
            {
                var startRaw = startCell.Text?.Trim() ?? "(trống)";
                var endRaw   = endCell.Text?.Trim()   ?? "(trống)";
                _importError = $"Không đọc được ngày tại B2 ({startRaw}) hoặc B3 ({endRaw}). " +
                               "Vui lòng định dạng theo dd/MM/yyyy hoặc yyyy-MM-dd.";
                StateHasChanged();
                return;
            }

            // Mapping cột → thứ
            var colToDay = new Dictionary<int, DayOfWeek>
            {
                {2, DayOfWeek.Monday}, {3, DayOfWeek.Tuesday},
                {4, DayOfWeek.Wednesday}, {5, DayOfWeek.Thursday},
                {6, DayOfWeek.Friday},   {7, DayOfWeek.Saturday}
            };

            // Mapping dòng → bữa
            var rowToBua = new Dictionary<int, (int Id, string Ten)>
            {
                {5, (1, "Sáng")}, {6, (2, "Trưa")}, {7, (3, "Xế")}
            };

            // Tập ngày trong khoảng
            var ngayList = new List<DateTime>();
            for (var d = ngayBatDau; d <= ngayKetThuc; d = d.AddDays(1))
                ngayList.Add(d);

            // Tập "đã có" trong tuần (nếu đang xem đúng tuần) — dùng lookup đơn giản
            var existKeys = new HashSet<(DateTime, int, string)>(
                _menuDict.SelectMany(kv => kv.Value.Select(t =>
                    (kv.Key.Item1, kv.Key.Item2, t.ten_thucdon.Trim().ToLower()))));

            _importRows = new();

            foreach (var (rowNum, buaInfo) in rowToBua)
            {
                foreach (var (colNum, dow) in colToDay)
                {
                    var cellText = sheet.Cells[rowNum, colNum].Text?.Trim() ?? "";
                    if (string.IsNullOrWhiteSpace(cellText)) continue;

                    var monList = System.Text.RegularExpressions.Regex
                        .Split(cellText, @"\s*/\s*")
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .Select(x => x.Trim())
                        .ToList();

                    var ngayPhuHop = ngayList.Where(n => n.DayOfWeek == dow).ToList();
                    if (!ngayPhuHop.Any())
                        ngayPhuHop = new List<DateTime>
                        {
                            ngayBatDau.AddDays((int)dow - (int)DayOfWeek.Monday)
                        };

                    foreach (var ngay in ngayPhuHop)
                    {
                        foreach (var mon in monList)
                        {
                            bool dup = existKeys.Contains((ngay.Date, buaInfo.Id, mon.ToLower()));
                            _importRows.Add(new ImportRow(
                                ngay, buaInfo.Id, buaInfo.Ten, mon,
                                true, dup, ""
                            ));
                        }
                    }
                }
            }

            if (_importRows.Count == 0)
            {
                _importError = "Không đọc được dữ liệu từ file!";
                StateHasChanged();
                return;
            }

            _importStep = 2;
        }
        catch (Exception ex)
        {
            _importError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        StateHasChanged();
    }

    private async Task ExecuteImport()
    {
        var toAdd = _importRows.Where(r => r.IsValid && !r.IsDuplicate).ToList();
        if (!toAdd.Any()) return;

        _isProcessing = true;
        StateHasChanged();
        try
        {
            int ok = 0;
            foreach (var row in toAdd)
            {
                try
                {
                    bool res = await ThongBaoServices.haddThucDon(
                        _maTruongBo, row.IdBua, row.TenBua, row.Ngay, row.TenThucDon);
                    if (res) ok++;
                }
                catch { /* tiếp tục */ }
            }
            _importSuccessCount = ok;
            _importStep         = 3;
            await LoadThucDon();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteImport error: {ex.Message}");
            await ShowToast("Import thất bại!", "error");
        }
        finally
        {
            _isProcessing = false;
            StateHasChanged();
        }
    }

    // ── TOAST ──
    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts     = new System.Threading.CancellationTokenSource();
        _toastMessage = msg;
        _toastType    = type;
        _toastVisible = true;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ── DOWNLOAD TEMPLATE ──
    /// <summary>
    /// Phân tích ngày từ ô Excel với nhiều định dạng khác nhau.
    /// Ưu tiên: OADate (số thực) → dd/MM/yyyy → yyyy-MM-dd → MM/dd/yyyy → TryParse mặc định
    /// </summary>
    private static bool TryParseFlexibleDate(OfficeOpenXml.ExcelRange cell, out DateTime result)
    {
        result = DateTime.MinValue;

        // 1. Ô có giá trị kiểu DateTime (Excel lưu Date cell thực sự)
        if (cell.Value is DateTime dtVal)
        {
            result = dtVal.Date;
            return true;
        }

        // 2. Ô có giá trị kiểu double → OADate (Excel lưu ngày dưới dạng số thực)
        if (cell.Value is double dblVal && dblVal > 0)
        {
            try
            {
                result = DateTime.FromOADate(dblVal).Date;
                return true;
            }
            catch { }
        }

        // 3. Phân tích từ chuỗi văn bản với nhiều format
        var text = cell.Text?.Trim();
        if (string.IsNullOrEmpty(text)) return false;

        // Bộ format thử theo thứ tự ưu tiên
        var formats = new[]
        {
            "dd/MM/yyyy",   // Việt Nam chuẩn
            "d/M/yyyy",     // Việt Nam rút gọn (8/1/2026)
            "dd/MM/yy",
            "d/M/yy",
            "yyyy-MM-dd",   // ISO 8601
            "yyyy/MM/dd",
            "MM/dd/yyyy",   // en-US
            "M/d/yyyy",
            "MM-dd-yyyy",
            "dd-MM-yyyy",
            "dd.MM.yyyy",
        };

        // Dùng CultureInfo.InvariantCulture để tránh bị ảnh hưởng bởi locale máy
        if (DateTime.TryParseExact(text, formats,
            System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var parsed))
        {
            result = parsed.Date;
            return true;
        }

        // 4. Fallback: DateTime.TryParse với locale VN rồi Invariant
        var vnCulture = new System.Globalization.CultureInfo("vi-VN");
        if (DateTime.TryParse(text, vnCulture, System.Globalization.DateTimeStyles.None, out var vnParsed))
        {
            result = vnParsed.Date;
            return true;
        }

        if (DateTime.TryParse(text, System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var ivParsed))
        {
            result = ivParsed.Date;
            return true;
        }

        return false;
    }


    private async Task DownloadTemplate()
    {
        try
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            using var ep = new ExcelPackage();
            var ws = ep.Workbook.Worksheets.Add("ThucDonTuan");

            // Tiêu đề
            ws.Cells[1, 1].Value = "THỰC ĐƠN TUẦN";
            ws.Cells[1, 1, 1, 7].Merge = true;
            ws.Cells[1, 1].Style.Font.Bold = true;
            ws.Cells[1, 1].Style.Font.Size = 14;
            ws.Cells[1, 1].Style.HorizontalAlignment = OfficeOpenXml.Style.ExcelHorizontalAlignment.Center;

            // Ngày bắt đầu / kết thúc
            ws.Cells[2, 1].Value = "Ngày bắt đầu:";
            ws.Cells[2, 2].Value = _weekStart.ToString("dd/MM/yyyy");
            ws.Cells[3, 1].Value = "Ngày kết thúc:";
            ws.Cells[3, 2].Value = _weekEnd.ToString("dd/MM/yyyy");

            // Header hàng 4: cột thứ
            ws.Cells[4, 1].Value = "Bữa ăn";
            string[] thuNames = { "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7" };
            for (int c = 0; c < 6; c++)
            {
                ws.Cells[4, c + 2].Value = $"{thuNames[c]} ({_weekStart.AddDays(c):dd/MM})";
                ws.Cells[4, c + 2].Style.Font.Bold = true;
            }

            // Dòng 5,6,7: Sáng, Trưa, Xế
            ws.Cells[5, 1].Value = "Bữa Sáng";
            ws.Cells[6, 1].Value = "Bữa Trưa";
            ws.Cells[7, 1].Value = "Bữa Xế";

            // Gợi ý
            ws.Cells[9, 1].Value = "Ghi chú: Nhập nhiều món trong 1 ô, phân cách bằng dấu /";
            ws.Cells[9, 1, 9, 7].Merge = true;
            ws.Cells[9, 1].Style.Font.Italic = true;
            ws.Cells[9, 1].Style.Font.Color.SetColor(System.Drawing.Color.Gray);

            ws.Column(1).Width = 14;
            for (int c = 2; c <= 7; c++) ws.Column(c).Width = 22;

            // Format header row
            ws.Cells[4, 1, 4, 7].Style.Fill.PatternType = OfficeOpenXml.Style.ExcelFillStyle.Solid;
            ws.Cells[4, 1, 4, 7].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.FromArgb(99, 102, 241));
            ws.Cells[4, 1, 4, 7].Style.Font.Color.SetColor(System.Drawing.Color.White);
            ws.Cells[4, 1, 4, 7].Style.Font.Bold = true;

            var bytes = ep.GetAsByteArray();
            var base64 = Convert.ToBase64String(bytes);
            var fileName = $"MauThucDonTuan_{_weekStart:ddMMyyyy}.xlsx";
            await JS.InvokeVoidAsync("downloadFileFromBase64", fileName, base64);
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error");
        }
    }

